import { strict as assert } from 'node:assert';
import { execFileSync } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { brotliCompressSync, constants, gzipSync } from 'node:zlib';

import { transformSync } from '@babel/core';
import terser from '@rollup/plugin-terser';
import { rollup } from 'rollup';

const entry = fileURLToPath(
  new URL('../src/ssr/fixtures/minimal-imperative.ts', import.meta.url),
);
const bundle = await rollup({
  input: entry,
  external: ['react', 'effector', 'effector-react'],
  plugins: [
    {
      name: 'strip-types',
      transform(code, id) {
        if (id !== entry) return;
        return transformSync(code, {
          filename: id,
          babelrc: false,
          configFile: false,
          presets: ['@babel/preset-typescript'],
        }).code;
      },
    },
  ],
});
try {
  const { output } = await bundle.generate({
    format: 'es',
    plugins: [terser({ module: true })],
  });
  const code = output[0].code;
  const brotli = brotliCompressSync(code, {
    params: { [constants.BROTLI_PARAM_QUALITY]: 11 },
  }).length;
  console.log(code);
  console.table({
    minimal: { bytes: Buffer.byteLength(code), gzip: gzipSync(code).length, brotli },
  });
  if (process.argv.includes('--check'))
    assert.ok(brotli <= 250, `Brotli budget exceeded: ${brotli} > 250`);
  if (process.argv.includes('--test')) {
    const root = fileURLToPath(new URL('..', import.meta.url));
    execFileSync('pnpm', ['build'], { cwd: root, stdio: 'inherit' });
    const dist = new URL('../dist/', import.meta.url);
    await mkdir(dist, { recursive: true });
    await writeFile(new URL('minimal-imperative.mjs', dist), code);
    await writeFile(
      new URL('minimal-vitest.config.mts', dist),
      `
      // Generated by scripts/check-minimal-imperative-bundle.mjs.
      import base from '../vitest.config.mts';
      import { mergeConfig } from 'vitest/config';
      import { fileURLToPath } from 'node:url';
      export default mergeConfig(base, {
        resolve: { alias: [{
          find: './fixtures/minimal-imperative',
          replacement: fileURLToPath(new URL('./minimal-imperative.mjs', import.meta.url)),
        }] },
      });
    `,
    );
    execFileSync(
      'pnpm',
      [
        'exec',
        'vitest',
        'run',
        'src/ssr/minimal-view-events.test.tsx',
        '--config',
        'dist/minimal-vitest.config.mts',
        '--maxWorkers=1',
        '--minWorkers=1',
      ],
      { cwd: root, env: { ...process.env, CI: '1' }, stdio: 'inherit' },
    );
  }
} finally {
  await bundle.close();
}
